xpath.attribute:
() => reviewerNoteOnly ? this.env.services.action.doAction(
                'ab_supplier_claim_cycle.action_supplier_claim_reviewer_note',
                {
                    additionalContext: { default_claim_id: props.threadId },
                    onClose: () => state.thread.fetchNewMessages(),
                }
            ) : this.toggleComposer('note')
